let filters = { minPrice:null, maxPrice:null, minMcap:null, maxMcap:null, minChg:null, maxChg:null };
let starred = new Set();

// ───── FORMAT HELPERS ─────
function fmt(n) {
  if(n===null||n===undefined) return '—';
  if(Math.abs(n)>=1e12) return '$'+(n/1e12).toFixed(2)+'T';
  if(Math.abs(n)>=1e9) return '$'+(n/1e9).toFixed(2)+'B';
  if(Math.abs(n)>=1e6) return '$'+(n/1e6).toFixed(2)+'M';
  if(Math.abs(n)>=1e3) return '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  return '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:8});
}
function fmtSupply(n, sym) {
  if(!n) return '—';
  if(n>=1e12) return (n/1e12).toFixed(2)+'T '+sym;
  if(n>=1e9) return (n/1e9).toFixed(2)+'B '+sym;
  if(n>=1e6) return (n/1e6).toFixed(2)+'M '+sym;
  return n.toLocaleString()+ ' '+sym;
}
function fmtPct(v) {
  if(v===null||v===undefined) return '—';
  const cls = v>0?'up':v<0?'down':'neutral';
  const sign = v>0?'+':'';
  return `<span class="${cls}">${sign}${v.toFixed(2)}%</span>`;
}
function fmtPrice(p) {
  if(p>=1000) return '$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(p>=1) return '$'+p.toFixed(2);
  if(p>=0.01) return '$'+p.toFixed(4);
  return '$'+p.toFixed(8);
}

// ───── SPARKLINE SVG ─────
function makeSpark(positive, color) {
  const pts = randSpark(positive);
  const d = sparkPath(pts);
  const endY = 4+(1-pts[pts.length-1])*32;
  // Area fill
  const firstX = 4, lastX = 96, firstY = 4+(1-pts[0])*32;
  const areaClose = ` L96,36 L4,36 Z`;
  const areaD = d + ` L96,${endY} L96,36 L4,36 Z`;
  return `<svg width="100" height="40" viewBox="0 0 100 40" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="${d} L96,${endY} L96,36 L4,36 Z" fill="${color}" fill-opacity="0.1"/>
    <path d="${d}" stroke="${color}" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

// ───── FILTER & SORT COINS ─────
function getFilteredCoins() {
  let coins = [...ALL_COINS];

  // Network filter
  if(currentNetwork !== 'all') {
    coins = coins.filter(c => c.network === currentNetwork);
    if(!coins.length) coins = ALL_COINS.slice(0,20); // fallback
  }

  // Category filter
  if(currentCategory === 'trending') {
    coins = [...coins].sort((a,b)=>Math.abs(b.h24)-Math.abs(a.h24));
  } else if(currentCategory === 'new') {
    coins = coins.slice(50).concat(coins.slice(0,10));
  } else if(currentCategory === 'visited') {
    coins = [...coins].sort(()=>Math.random()-.5);
  } else if(currentCategory === 'watchlist') {
    if(starred.size===0) return [];
    coins = coins.filter(c=>starred.has(c.sym));
  } else if(currentCategory === 'prediction') {
    coins = coins.filter(c=>c.price<1);
  }

  // Range filters
  if(filters.minPrice!==null) coins=coins.filter(c=>c.price>=filters.minPrice);
  if(filters.maxPrice!==null) coins=coins.filter(c=>c.price<=filters.maxPrice);
  if(filters.minMcap!==null) coins=coins.filter(c=>c.mcap>=filters.minMcap);
  if(filters.maxMcap!==null) coins=coins.filter(c=>c.mcap<=filters.maxMcap);
  if(filters.minChg!==null) coins=coins.filter(c=>c.h24>=filters.minChg);
  if(filters.maxChg!==null) coins=coins.filter(c=>c.h24<=filters.maxChg);

  // Sort
  coins.sort((a,b)=>{
    let av,bv;
    switch(sortKey) {
      case 'price': av=a.price; bv=b.price; break;
      case 'h1': av=a.h1; bv=b.h1; break;
      case 'h24': av=a.h24; bv=b.h24; break;
      case 'd7': av=a.d7; bv=b.d7; break;
      case 'vol': av=a.vol; bv=b.vol; break;
      case 'mcap': default: av=a.mcap; bv=b.mcap; break;
    }
    return (av-bv)*sortDir;
  });

  return coins;
}

// ───── RENDER TABLE ─────
function renderTable() {
  const coins = getFilteredCoins();
  const start = (currentPage-1)*100;
  const pageCoins = coins.slice(start, start+100);
  const tbody = document.getElementById('tableBody');

  if(pageCoins.length===0) {
    tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:48px;color:var(--text-secondary)">
      <i class="ri-database-2-line" style="font-size:32px;display:block;margin-bottom:8px"></i>
      No assets match your current filters.
    </td></tr>`;
    document.getElementById('paginationInfo').textContent = 'Showing 0 assets';
    return;
  }

  tbody.innerHTML = pageCoins.map((coin, idx) => {
    const i = start+idx;
    const sparkColor = coin.d7>=0 ? '#16c784' : '#ea3943';
    const spark = visibleCols['col-spark'] ? makeSpark(coin.d7>=0, sparkColor) : '';
    const supplyPct = coin.supplyMax ? (coin.supply/coin.supplyMax)*100 : 60+Math.random()*30;
    const isStarred = starred.has(coin.sym);

    return `<tr>
      <td class="rank-col">
        <button class="star-btn ${isStarred?'starred':''}" onclick="toggleStar(event,'${coin.sym}')" title="Add to watchlist">
          <i class="${isStarred?'ri-star-fill':'ri-star-line'}"></i>
        </button>${i+1}
      </td>
      <td>
        <div class="coin-cell">
          <div class="coin-icon" style="background:${coinColor(coin.sym)}">${coin.sym.charAt(0)}</div>
          <div>
            <div class="coin-name">${coin.name}</div>
            <div class="coin-symbol">${coin.sym}</div>
          </div>
        </div>
      </td>
      <td class="price-col">${fmtPrice(coin.price)}</td>
      <td class="pct-col col-1h ${visibleCols['col-1h']?'':'hidden'}">${fmtPct(coin.h1)}</td>
      <td class="pct-col col-24h ${visibleCols['col-24h']?'':'hidden'}">${fmtPct(coin.h24)}</td>
      <td class="pct-col col-7d ${visibleCols['col-7d']?'':'hidden'}">${fmtPct(coin.d7)}</td>
      <td class="mcap-col col-mcap ${visibleCols['col-mcap']?'':'hidden'}">${fmt(coin.mcap)}</td>
      <td class="vol-col col-vol ${visibleCols['col-vol']?'':'hidden'}">${fmt(coin.vol)}</td>
      <td class="supply-col col-supply ${visibleCols['col-supply']?'':'hidden'}">
        <div>${fmtSupply(coin.supply, coin.sym)}</div>
        <div class="supply-bar"><div class="supply-bar-fill" style="width:${Math.min(100,supplyPct).toFixed(0)}%"></div></div>
      </td>
      <td class="col-spark ${visibleCols['col-spark']?'':'hidden'}" style="text-align:center">${spark}</td>
    </tr>`;
  }).join('');

  // Update pagination info
  const total = coins.length;
  const s = start+1, e = Math.min(start+100, total);
  document.getElementById('paginationInfo').textContent = `Showing ${s}–${e} of ${total.toLocaleString()} assets`;

  // Update header column visibility
  document.querySelectorAll('[class*="col-"]').forEach(el => {
    const classes = el.className.split(' ');
    classes.forEach(c => {
      if(visibleCols.hasOwnProperty(c)) {
        el.classList.toggle('hidden', !visibleCols[c]);
      }
    });
  });
}

